			freetext.setIfNotExists("Type", Name.get("Annot"));
			freetext.setIfNotExists("Subtype", Name.get("FreeText"));
			freetext.set(oldAnnotation ? "M" : "CreationDate", `D:${getModificationDate(date)}`);
			if (oldAnnotation) freetext.delete("RC");
